'use strict';
// Contract tests: written from the specification examples. Do not edit; fix src/core.js instead.
const test = require('node:test');
const assert = require('node:assert/strict');
const core = require('../src/core');

const plain = (v) => JSON.parse(JSON.stringify(v === undefined ? null : v));

test('core exports every specified function', () => {
  for (const n of ["detectSbom", "normalizeComponents", "purlType", "licenseCategory", "reportSummary", "reportComponents", "reportDuplicates", "reportLicenseRisk", "reportMinimumElements"]) assert.equal(typeof core[n], 'function', n);
});

test("detectSbom example 1", () => {
  assert.deepStrictEqual(plain(core.detectSbom("{\"bomFormat\": \"CycloneDX\", \"specVersion\": \"1.5\", \"metadata\": {\"timestamp\": \"2026-01-05T10:00:00Z\", \"authors\": [{\"name\": \"Build Team\"}], \"component\": {\"type\": \"application\", \"name\": \"shop-app\", \"version\": \"2.0.0\"}}, \"components\": [{\"type\": \"library\", \"name\": \"lodash\", \"version\": \"4.17.21\", \"purl\": \"pkg:npm/lodash@4.17.21\", \"licenses\": [{\"license\": {\"id\": \"MIT\"}}], \"supplier\": {\"name\": \"OpenJS\"}}, {\"type\": \"library\", \"name\": \"readline-x\", \"version\": \"1.2.0\", \"purl\": \"pkg:npm/readline-x@1.2.0\", \"licenses\": [{\"expression\": \"GPL-3.0-only OR MIT\"}]}, {\"type\": \"library\", \"name\": \"libfoo\", \"version\": \"\", \"purl\": \"pkg:pypi/libfoo\", \"licenses\": [{\"license\": {\"id\": \"GPL-2.0-only\"}}]}, {\"type\": \"library\", \"name\": \"lodash\", \"version\": \"4.17.15\", \"purl\": \"pkg:npm/lodash@4.17.15\", \"licenses\": [{\"license\": {\"name\": \"Custom Corp License\"}}]}], \"dependencies\": [{\"ref\": \"shop-app\", \"dependsOn\": [\"pkg:npm/lodash@4.17.21\"]}]}")), {"format": "CycloneDX", "version": "1.5"});
});

