  assert.deepStrictEqual(plain(core.detectSbom("{\"spdxVersion\": \"SPDX-2.3\", \"SPDXID\": \"SPDXRef-DOCUMENT\", \"name\": \"web\", \"creationInfo\": {\"created\": \"2026-01-05T10:00:00Z\", \"creators\": [\"Tool: scanner-1.0\"]}, \"packages\": [{\"SPDXID\": \"SPDXRef-Package-a\", \"name\": \"requests\", \"versionInfo\": \"2.31.0\", \"licenseConcluded\": \"Apache-2.0\", \"licenseDeclared\": \"NOASSERTION\", \"externalRefs\": [{\"referenceCategory\": \"PACKAGE-MANAGER\", \"referenceType\": \"purl\", \"referenceLocator\": \"pkg:pypi/requests@2.31.0\"}], \"supplier\": \"Organization: PSF\"}, {\"SPDXID\": \"SPDXRef-Package-b\", \"name\": \"zlib\", \"versionInfo\": \"1.3\", \"licenseConcluded\": \"NOASSERTION\", \"licenseDeclared\": \"Zlib\"}], \"relationships\": [{\"spdxElementId\": \"SPDXRef-Package-a\", \"relationshipType\": \"DEPENDS_ON\", \"relatedSpdxElement\": \"SPDXRef-Package-b\"}]}")), {"format": "SPDX", "version": "SPDX-2.3"});
