test("reportSummary example 1", () => {
  const md = core.reportSummary("{\"bomFormat\": \"CycloneDX\", \"specVersion\": \"1.5\", \"metadata\": {\"timestamp\": \"2026-01-05T10:00:00Z\", \"authors\": [{\"name\": \"Build Team\"}], \"component\": {\"type\": \"application\", \"name\": \"shop-app\", \"version\": \"2.0.0\"}}, \"components\": [{\"type\": \"library\", \"name\": \"lodash\", \"version\": \"4.17.21\", \"purl\": \"pkg:npm/lodash@4.17.21\", \"licenses\": [{\"license\": {\"id\": \"MIT\"}}], \"supplier\": {\"name\": \"OpenJS\"}}, {\"type\": \"library\", \"name\": \"readline-x\", \"version\": \"1.2.0\", \"purl\": \"pkg:npm/readline-x@1.2.0\", \"licenses\": [{\"expression\": \"GPL-3.0-only OR MIT\"}]}, {\"type\": \"library\", \"name\": \"libfoo\", \"version\": \"\", \"purl\": \"pkg:pypi/libfoo\", \"licenses\": [{\"license\": {\"id\": \"GPL-2.0-only\"}}]}, {\"type\": \"library\", \"name\": \"lodash\", \"version\": \"4.17.15\", \"purl\": \"pkg:npm/lodash@4.17.15\", \"licenses\": [{\"license\": {\"name\": \"Custom Corp License\"}}]}], \"dependencies\": [{\"ref\": \"shop-app\", \"dependsOn\": [\"pkg:npm/lodash@4.17.21\"]}]}");
  assert.equal(typeof md, 'string');
  for (const s of ["# SBOM Summary", "CycloneDX 1.5 SBOM for shop-app 2.0.0.", "4 components.", "3 with a version, 4 with a license, 4 with a package URL.", "| npm | 3 |", "| pypi | 1 |"]) assert.ok(md.includes(s), 'missing: ' + s);
});

